function row(p){const design=directoryDesigns.bySlug.get(p.slug);const apache=p.originalId===16;const styles=`--card-paper:${design.paper};--card-accent:${design.accent};--card-h:${design.hue};--card-angle:${design.angle}deg;--card-x:${design.x}%;--card-y:${design.y}%;--card-spread:${design.spread}%`;return `<li class="nation-row ${apache?'apache-directory-card':'directory-visual-card'}" style="${styles}" data-card-design="${design.signature}" data-nation data-slug="${p.slug}" data-search="${e(norm([p.name,p.preferredName,...(p.searchTerms||[]),p.region,p.kind,p.overview,p.relationshipNote].join(' ')))}" data-sort="${e(norm(p.name))}" data-letter="${norm(p.name).charAt(0).toUpperCase()}" data-region="${e(p.regionGroups.join('|'))}" data-status="${e(depth(p))}" data-sources="${p.sources.length}" data-reviewed="${checkedSources(p)}" data-added="${p.added}">${!apache?`<span class="directory-card-art art-${design.composition}${design.image?' has-photo':''}" aria-hidden="true"${design.image?` style="background-image:url('${e(design.image)}')"`: ''}>${!design.image?`<span>${e(design.initial)}</span>`:''}</span>`:''}<a class="nation-link" href="${href(p)}"><div><h3 class="nation-title">${e(p.name)}${p.added?'<span class="added-tag">Added</span>':''}</h3><span class="nation-alt">${e(p.preferredName&&p.preferredName!==p.name?p.preferredName:p.kind)}</span>${apache?'<span class="apache-card-credit">Basket · The Met<br>Image credits in profile</span>':design.image?`<span class="directory-card-credit">${e(design.credit)}<br>${p.originalId===244?'Photo credit &amp; license in About':'Image credits in profile'}</span>`:''}</div><div class="row-meta"><span class="row-region">${e(p.region)}</span><span class="tiny-label">${p.sources.length} ${p.sources.length===1?'source':'sources'} · ${status(p)}</span></div><span class="row-arrow" aria-hidden="true">↗</span></a><button class="bookmark" data-bookmark="${p.slug}" data-name="${e(p.name)}" aria-label="Save ${e(p.name)} to reading list" aria-pressed="false">${bookmarkIcon}</button></li>`;}
const homePhotographs=JSON.parse(fs.readFileSync(path.join(cwd,'data/homepage-photographs.json'),'utf8')).images;
function culturalPhoto(photo,{hero=false}={}){return `<figure class="culture-photo ${hero?'culture-photo-hero':''}" id="photo-${e(photo.id)}"><a class="culture-image" href="${e(photo.sourcePage)}" target="_blank" rel="noopener noreferrer" aria-label="Original photograph and credits: ${e(photo.title)}"><img src="${e(photo.asset)}" width="${photo.width}" height="${photo.height}" alt="${e(photo.altText)}" loading="${hero?'eager':'lazy'}" decoding="async"></a><figcaption><h3>${e(photo.title)}</h3><p>${e(photo.caption)}</p>${photo.artistCredit?`<p class="artist-credit">${e(photo.artistCredit)}</p>`:''}<div class="photo-credit">Photo: ${e(photo.photoCredit)} · <a href="${e(photo.sourcePage)}" target="_blank" rel="noopener noreferrer">Source</a> · <a href="${e(photo.licenseUrl)}" target="_blank" rel="noopener noreferrer">${e(photo.licenseShort)}</a><span>Resized &amp; compressed · <a href="about/#photography">Full credits</a></span></div></figcaption></figure>`;}
const historicalMapFeature=`<figure class="culture-photo culture-photo-hero historical-map-feature"><a class="culture-image" href="https://www.loc.gov/item/97683586/" target="_blank" rel="noopener noreferrer" aria-label="View the Library of Congress record for Manatvs gelegen op de Noot Riuier"><img src="assets/historical-maps/manatus-owner-supplied.png" width="1095" height="742" alt="A richly colored seventeenth-century Dutch colonial map of Manhattan and Indigenous settlements along the Hudson River." fetchpriority="high" decoding="async"></a><figcaption><h3><em>Manatvs gelegen op de Noot Riuier</em></h3><p>A striking Dutch colonial map depicting Indigenous settlements and the region around Manhattan.</p><div class="photo-credit">Joan Vinckeboons (Vingboons); surviving copy described as ca. 1665 after a 1639 map · <a href="https://www.loc.gov/item/97683586/" target="_blank" rel="noopener noreferrer">Library of Congress, Geography and Map Division</a> · <a href="about/#map-backgrounds">Dating, image provenance &amp; reuse notes</a></div></figcaption></figure>`;
const cultureGallery=`<section class="home-culture" aria-labelledby="culture-title"><div class="culture-heading"><div><div class="eyebrow">People · Art · Cultural life</div><h2 id="culture-title">Many traditions. Individual stories.</h2></div><p>Meet a maker, look closely at an object, and follow each photograph into its own context.</p></div><div class="culture-grid">${homePhotographs.filter(p=>p.role==='gallery').map(p=>culturalPhoto(p)).join('')}</div></section>`;
function homeImageCredits(){return `<h3>People, art and museum photographs</h3><p>These are real photographs of particular people, events and objects. Their captions identify the available context, rather than treating one tradition as universal. All four web versions retain the source frame, with proportional resizing and compression; the Lyle Harvey source already had a documented crop. No generated elements, motif extraction or content alteration was used.</p><ul>${homePhotographs.map(p=>`<li><strong>${e(p.title)}</strong> — ${e(p.caption)} ${p.artistCredit?e(p.artistCredit)+' ':''}Photograph/image: ${e(p.photoCredit)}. <a href="${e(p.sourcePage)}" target="_blank" rel="noopener noreferrer">Original source and attribution</a> · <a href="${e(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">${e(p.licenseShort)}</a> · <a href="../${e(p.asset)}">Web image</a>. ${e(p.changes)}${p.adaptationLicense?' '+e(p.adaptationLicense):''}</li>`).join('')}</ul><p>The Met basket’s maker and individual photographer are not named in its source record; this atlas does not supply invented names. The wampum photograph documents a public museum display; no particular maker, nation, treaty or object date is assigned from the uploader’s filename. Photo permissions and historical object attribution are separate questions. <a href="../assets/credits.json">Download the image-credit record</a>.</p>`;}
const languageMapPdf='https://americanindian.si.edu/nk360/code-talkers/assets/print/code-talkers-native-languages-map-languages-full.pdf';
const languageMapPage=`<main id="main" class="wrap historical-library"><section class="page-hero historic-hero"><div class="eyebrow">A zoomable reference map</div><h1>Native languages<br><em>of North America</em></h1><p>Explore Ives Goddard’s map of Native languages and language families across much of North America, focused mainly north of Mexico. The revised and enlarged edition dates to 1999. Open the full-page PDF in your browser to zoom and pan across its labels and index.</p><div class="historic-intro-links"><a href="${languageMapPdf}" target="_blank" rel="noopener noreferrer">Open the zoomable Smithsonian PDF ↗</a><a href="../historical-maps/">Visit the historical map room ↗</a></div></section><aside class="historic-context"><strong>Read the map’s time period carefully.</strong> This is a language-family map, not a map of every nation or a record of fixed political borders. Its published description places language areas at earliest European contact, which happened at different times in different regions. The areas are approximate, fuzzy, and may be uncertain. Its focus is north of Mexico; it does not provide full coverage of Indigenous peoples in Mexico, Central America, or the Caribbean. It should not be read as a single snapshot of North America in 1500 or as evidence that a people was absent where no label appears.</aside><section class="historic-about"><div><h2>View the full map</h2><p>The PDF is hosted by the Smithsonian’s National Museum of the American Indian, Native Knowledge 360°. Use your browser’s PDF controls to zoom, pan, search text where supported, or download the file from the viewer.</p><p><a class="historic-primary" href="${languageMapPdf}" target="_blank" rel="noopener noreferrer">Open the full-page PDF in a new tab ↗</a></p></div><div><h2>Map credit and scope</h2><p><em>Native Languages and Language Families of North America</em>, compiled by Ives Goddard; revised and enlarged edition with additions and corrections, 1999. The PDF identifies language families and linguistic units. It does not map individual nations’ territories.</p><p>The Atlas links to the Smithsonian-hosted PDF rather than copying the file. The map is a scholarly orientation reference; consult the cited sources and community accounts on individual profile pages for nation-specific histories.</p></div></section></main>`;
const languageMapPromo=`<section class="language-map-feature temple-language-feature" id="language-map-reference" aria-labelledby="language-feature-title"><div class="language-feature-copy"><h2 id="language-feature-title">Explore the Smithsonian language map</h2><p>Look closely at North America’s language families. Open the Smithsonian-hosted PDF and zoom into the details.</p><a class="language-feature-button" href="language-map/">Open the language map <span aria-hidden="true">↗</span></a><p class="language-feature-note">Approximate language-family areas at different first-contact periods. This is not a single map of nations in 1500, and coverage of Mexico and Central America is limited.</p></div><p class="temple-photo-credit">El Osario, Chichén Itzá · Photo: Álvaro de la Paz Franco<br><a href="https://commons.wikimedia.org/wiki/File:Chich%C3%A9n_Itz%C3%A1_-_Osario_02.jpg" target="_blank" rel="noopener noreferrer">Photo source</a> · <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noopener noreferrer">CC0 1.0</a> · <a href="data/language-map-feature-photo.json">Display notes</a></p></section>`;
const indigenousLandscapeMap=`<section id="historic-landscape" class="historic-landscape" aria-label="Indigenous American nations, c.16th century — historical reconstruction"><figure class="historic-map-figure"><div class="historic-map-viewport" data-historical-map-viewer tabindex="0" role="region" aria-label="Zoomable map image. Scroll or use plus and minus keys to zoom, arrow keys to pan, and zero to reset."><img src="assets/indigenous-american-nations-16th-century-2024.jpg" width="8900" height="5600" alt="Peter Klumpenhower’s c. 16th-century reconstruction showing many Indigenous nations across North America, with regional inset maps and a name index. Areas are approximate and do not show fixed, comprehensive borders." loading="lazy" decoding="async" draggable="false"></div><noscript><p class="historic-map-noscript">Use the full-resolution image link below to zoom when JavaScript is unavailable.</p></noscript><figcaption><strong>Map:</strong> Peter Klumpenhower (Diné), <em>Indigenous American Nations, c.16th Century</em>, second edition (2024). The creator dedicates the map and its geometry to the public domain; the Atlas provides this courtesy credit and does not imply the creator’s endorsement. <a href="assets/indigenous-american-nations-16th-century-2024.jpg" target="_blank" rel="noopener noreferrer">Open the full-resolution image ↗</a> · <a href="https://indigamerica.blogspot.com/2024/07/indigenous-american-nations-c16th.html" target="_blank" rel="noopener noreferrer">Creator’s edition notes</a> · <a href="https://indigamerica.blogspot.com/p/downloads.html" target="_blank" rel="noopener noreferrer">Original download and reuse terms</a> · <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noopener noreferrer">CC0 1.0</a>.</figcaption></figure></section>`;
