let home=`<main id="main"><div class="wrap"><section class="hero brand-home" aria-labelledby="hero-title"><h1 id="hero-title" class="brand-accessible-title">Robey’s Atlas of Indigenous North America</h1><img class="brand-home-image" src="assets/robeys-atlas-brand-collage.jpg" width="1280" height="837" alt="Historical portraits, basketry, weaving and wampum surrounding the title Robey’s Atlas of Indigenous North America." fetchpriority="high" decoding="async"><div class="brand-home-intro"><div><div class="eyebrow">Peoples · Places · Living histories</div><p>Explore the peoples, nations, and communities of Indigenous North America. Find a starting point, understand the names, and follow carefully organized sources into a deeper history.</p></div><div class="hero-links"><a href="#map">Explore the map ↓</a><a href="#directory">Browse the directory ↗</a><a href="#historic-landscape">View the c. 16th-century map ↓</a></div><p class="brand-image-credit"><a href="about/#brand-image">Brand collage supplied by the Atlas owner</a></p></div></section>${regionMap.home}${indigenousLandscapeMap}${historicalMaps.homePromo}${languageMapPromo}<section id="directory" class="directory-scenic" data-directory><div class="directory-heading"><div class="directory-heading-copy"><h2>The directory</h2><span>Names, homelands &amp; reading paths</span></div><dl class="directory-totals" aria-label="Directory totals"><div><dt>Directory entries</dt><dd>${total.toLocaleString('en-US')}</dd></div><div><dt>Linked resources</dt><dd>${allSources.length.toLocaleString('en-US')}</dd></div></dl></div><p class="directory-photo-credit">Backdrop: Canyon de Chelly · Navajo Nation · Photo: Margie Roesch · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a> · <a href="about/#photography">Photo source &amp; credit</a></p><div class="search-box"><label class="search-icon" for="search" aria-label="Search the directory">⌕</label><input id="search" type="search" placeholder="Search a name, alternate name, or homeland…" autocomplete="off" aria-label="Search names, alternate names and homelands"><button class="clear-search" aria-label="Clear search" hidden>Clear</button></div><div class="alphabet" role="group" aria-label="Browse alphabetically"><button class="active" data-letter="" aria-pressed="true">All</button>${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(x=>`<button data-letter="${x}" aria-pressed="false">${x}</button>`).join('')}</div><div class="directory-layout"><aside class="filters" aria-label="Directory filters"><div class="filter-group"><label class="filter-label" for="region">Homeland / region</label><select id="region"><option value="">All regions</option>${options(regions)}</select></div><div class="filter-group"><label class="filter-label" for="research-status">Reading depth</label><select id="research-status"><option value="">All entries</option><option value="developed-profile">Expanded profiles</option><option value="reviewed-minimum">12+ inspected sources</option><option value="researched">Brief cited overviews</option><option value="source-guide">Source guides</option></select></div><div class="filter-group filter-checks"><label class="filter-check"><input type="checkbox" id="added-only">New additions only</label><label class="filter-check"><input type="checkbox" id="saved-only">My saved entries</label></div><div class="filter-group filter-explanation"><span class="filter-label">A note on names</span><p class="filter-help">Some entries are alternate names or broader groupings. Open a profile to see naming notes and related communities.</p></div><button class="text-button reset-filter" data-reset>Reset all filters</button></aside><div><div class="result-toolbar"><span id="result-count" role="status" aria-live="polite">${total} entries</span><label>Sort <select id="sort" aria-label="Sort directory"><option value="az">Name A–Z</option><option value="za">Name Z–A</option><option value="sources">Most sources</option></select></label></div><noscript><p class="noscript">All entries are listed below. Search, filters, and saving require JavaScript; every profile and source link works without JavaScript.</p></noscript><ul class="results" id="nation-results">${profiles.map(row).join('')}</ul><div class="empty" id="empty-results" hidden><h3>No entries found.</h3><p>Try another spelling, a broader name, or fewer filters.</p><button class="text-button" data-reset>Clear the filters</button></div><button class="load-more" id="load-more" hidden>Show more entries</button></div></div></section></div><section class="reading-band homepage-manatus" id="reading-with-context"><div class="wrap"><div><div class="eyebrow">Reading with context</div><h2>Start with the community.<br>Keep following the sources.</h2><p>A single label can cover many distinct communities. A source can tell one part of a much larger story. These reference collections help you find your next step.</p></div><div class="reading-links"><p class="map-background-credit">Background: <em>Manatvs</em>, Joan Vinckeboons (Vingboons), surviving copy after a 1639 map. <a href="https://www.loc.gov/item/97683586/">Library of Congress, Geography and Map Division</a> · <a href="about/#map-backgrounds">Dates, credit &amp; reuse</a>.</p><a href="sources/">Explore the reading room <span>↗</span></a><a href="about/#names">Understand names &amp; relationships <span>↗</span></a><a href="index.html?added=1#directory">See additions to the original list <span>↗</span></a></div></div></section></main>`;

