function cite(p,ids){return `<p class="citations">Read the sources ${ids.map(id=>{const idx=p.sources.findIndex(s=>s.id===String(id));return idx<0?'':`<a class="citation" href="#source-${idx+1}">[${idx+1}] ${e(p.sources[idx].publisher)}</a>`;}).join(' ')}</p>`;}
function inspectedLinks(s){const links=(s.inspectedSubresources||[]).filter(r=>/^https?:\/\//.test(r.url||''));return links.length?`<div class="source-inspected-links"><p><strong>Inspected material and access routes</strong></p><ul>${links.map(r=>`<li><a href="${e(r.url)}" target="_blank" rel="noopener noreferrer">${e(r.title||'Related inspected resource')} ↗</a>${r.scope?`<span> — ${e(r.scope)}</span>`:''}</li>`).join('')}</ul></div>`:'';}
const isIndigenousLed = s => s.indigenousLed === true || s.type?.toLowerCase().startsWith('indigenous-led');
function sourceCard(s,{index=0,profile=false,base=''}={}){return `<article class="source-card" id="source-${index+1}" ${profile?`data-profile-source data-indigenous="${isIndigenousLed(s)}"`:`data-source-card data-type="${e(s.type)}" data-topics="${e(s.topics.join(' '))}" data-search="${e([s.title,s.publisher,s.annotation,...s.topics,...(s.nations||[]).map(n=>n.name)].join(' '))}"`}><div class="source-meta"><span class="source-type ${isIndigenousLed(s)?'':'institutional'}">${e(s.type)}</span><span>${e(s.publisher)}</span><span>Source ${index+1}</span>${s.countsTowardMinimum===false?'<span>Supporting reference · outside substantive inspected count</span>':''}</div><h3><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} <span aria-hidden="true">↗</span></a></h3><p>${e(s.annotation||'Open this source to continue your research.')}</p>${s.contentReviewScope?`<p class="source-accessed">Inspection scope: ${e(s.contentReviewScope)}</p>`:''}${inspectedLinks(s)}${s.accessed?`<p class="source-accessed">${s.contentReviewedAt?'Content checked':'Accessed'} ${e(dateLabel(s.contentReviewedAt||s.accessed))}</p>`:''}<a class="source-url" href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.url)}</a><div class="source-topics">${s.topics.map(t=>`<span>${e(t)}</span>`).join('<span aria-hidden="true">·</span>')}</div>${!profile&&s.nations?.length?`<div class="source-nations">In the directory: ${s.nations.map(n=>`<a href="${base}nations/${n.slug}/">${e(n.name)}</a>`).join('<span aria-hidden="true">·</span>')}</div>`:''}</article>`;}

const leadCatalog=JSON.parse(fs.readFileSync(path.join(cwd,'data/owner-reading-leads.json'),'utf8'));
const ownerStudies=JSON.parse(fs.readFileSync(path.join(cwd,'data/owner-studies.json'),'utf8').replace(/^\uFEFF/,''));
const studyLinks=(key,base='../')=>{const d=ownerStudies.find(x=>x.key===key);return d?'<p class="study-actions"><a href="'+base+'studies/'+slug(key)+'/">Read the full study →</a> · <a href="'+base+e(d.download)+'" download>Download Word (.docx)</a></p>':'';};
const leadURLKey=url=>{const u=new URL(url);u.hash='';u.hostname=u.hostname.replace(/^www\./,'');return u.href.replace(/\/$/,'');};
function researchLeadSection(p){
 if(!p.researchLeads?.length)return '';
 const groups=new Map();
 for(const s of p.researchLeads){if(!groups.has(s.documentKey))groups.set(s.documentKey,[]);groups.get(s.documentKey).push(s);}
 return '<section class="research-leads" id="reading-leads"><div class="eyebrow">Continue the research</div><h2>Suggested reading and supporting references</h2><p>These collections preserve links from supplied studies and further research leads. The collection notes explain their provenance and review status. Links already used above point to their source cards. Supporting references and unread leads are excluded from the substantive inspected-source count.</p>'+[...groups.values()].map(items=>'<details class="lead-group" open><summary>'+e(items[0].documentTitle)+' · '+items.length+' links</summary><p class="lead-context">'+e(items[0].contextNote)+'</p><ul class="lead-list">'+items.map(s=>{
 const idx=p.sources.findIndex(t=>t.id===s.matchedSourceId||leadURLKey(t.url)===leadURLKey(s.url));
 const status=s.supportingReview?'Supporting material inspected — outside substantive inspected count':idx<0?'Awaiting original-source review':p.sources[idx].contentReviewedAt?'Content checked — see the annotation’s scope':'Already listed — content review pending';
 return '<li><a href="'+e(idx<0?s.url:'#source-'+(idx+1))+'"'+(idx<0?' target="_blank" rel="noopener noreferrer"':'')+'>'+e(s.title)+'</a><span class="lead-status">'+e(status)+'</span><a class="source-url" href="'+e(s.url)+'" target="_blank" rel="noopener noreferrer">'+e(s.url)+'</a>'+(s.linkNote?'<p class="lead-access">'+e(s.linkNote)+'</p>':'')+'</li>';
 }).join('')+'</ul></details>').join('')+'<p><a href="../../reading-leads/">Browse all supplied reading collections →</a></p></section>';
}
const leadPage=document('Suggested reading collections','Source links supplied through owner studies, organized by nation and historical topic.',
 '<main id="main" class="wrap"><section class="page-hero"><div class="eyebrow">The research queue</div><h1>Studies &amp;<br>source collections.</h1><p>'+leadCatalog.documents.length+' supplied studies contribute '+new Set(leadCatalog.documents.flatMap(d=>d.links.map(s=>s.url))).size+' distinct URLs. Each collection is linked to the relevant directory entries. These are reading leads; their inclusion does not establish content review, accuracy, or research completion.</p></section><article class="prose">'+leadCatalog.documents.map(d=>'<section id="'+e(d.key)+'"><h2>'+e(d.title)+'</h2><p>'+e(d.contextNote)+'</p>'+studyLinks(d.key)+'<p>'+d.links.length+' links · '+d.originalIds.map(id=>{const p=byId.get(id);return '<a href="../nations/'+p.slug+'/#reading-leads">Open '+e(p.name)+'’s collection →</a>';}).join(' · ')+'</p></section>').join('')+'<p><a href="../data/owner-reading-leads.json" download>Download the supplied URL catalog</a></p></article></main>','../','sources');

function profilePage(p){const base='../../';const mapSection=historicalMaps.profileSection(p);const related=[...new Set(p.relatedOriginalIds.map(Number))].map(n=>byId.get(n)).filter(x=>x&&x.slug!==p.slug);let sections=p.sections.map((s,i)=>`<section class="profile-section" id="section-${i+1}"><span class="section-num">${String(i+1).padStart(2,'0')}</span><h2>${e(s.title)}</h2><p>${e(s.text)}</p>${cite(p,s.sourceIds)}</section>`).join('');return document(p.name,p.overview,`<main id="main" class="wrap"><div class="breadcrumb"><a href="../../index.html#directory">The directory</a><span>/</span><span>${e(p.name)}</span></div>${profileVisuals.banner(p,base,e)}${p.originalId===16?`<div class="apache-collage-intro" aria-label="Apache material culture photographs"><figure class="collage-met"><img src="../../assets/home-apache-storage-basket-met.webp" alt="Tall Apache storage basket with dark geometric weaving, ca. 1890"><figcaption>Apache storage basket · The Met</figcaption></figure><figure class="collage-curtis"><img src="../../assets/apache-still-life-curtis-1907.jpg" alt="Edward Curtis photograph of nine baskets, bowls and jars arranged as an Apache still life"><figcaption>Edward S. Curtis · c. 1907 · Library of Congress</figcaption></figure><figure class="collage-usgs"><img src="../../assets/apache-attributed-basket-usgs.jpg" alt="Shallow patterned basket attributed, with uncertainty, to Apache makers by the USGS"><figcaption>Attributed to Apache · USGS Museum Staff</figcaption></figure><a class="collage-credit-link" href="#apache-image-credits">Photographs &amp; credits ↓</a></div>`:''}<section class="profile-hero ${p.originalId===16?'apache-basket-hero':''}"><div><div class="eyebrow">${e(p.kind)}${p.added?' · Added to the original list':''}</div><h1>${e(p.name)}</h1>${p.preferredName&&p.preferredName!==p.name?`<p class="alt-name">Also find this entry through: ${e(p.preferredName)}</p>`:''}<p class="overview">${e(p.overview)}</p>${p.sources.length?cite(p,p.overviewSourceIds||p.sections[0]?.sourceIds||[p.sources[0].id]):''}<div class="profile-actions"><button data-bookmark="${p.slug}" data-name="${e(p.name)}" data-text-button aria-pressed="false">Save to reading list</button><a href="#sources">Go to ${p.sources.length} sources ↓</a><button data-print>Print / save PDF</button></div></div><dl class="profile-facts">${p.mapRegions?.length?`<div class="fact map-profile-fact"><dt>Explore on the map</dt><dd>${p.mapRegions.map(r=>`<a href="../../index.html?place=${e(r.id)}#map">${e(r.name)}</a>`).join(' · ')}</dd><dd class="map-profile-note">See each region’s evidence for historical or present-day scope.</dd></div>`:''}<div class="fact"><dt>Homeland / region</dt><dd>${e(p.region)}</dd></div><div class="fact"><dt>Research depth</dt><dd><span class="status-pill ${p.researchStatus==='researched'?'':'guide'}">${status(p)}</span></dd></div><div class="fact"><dt>Source collection</dt><dd>${p.sources.length} annotated resources · ${p.sources.filter(s=>isIndigenousLed(s)).length} Indigenous-led</dd></div><div class="fact"><dt>Inspected sources</dt><dd>${checkedSources(p)} substantive works · target about ${minimumSources}</dd></div><div class="fact"><dt>Initial adequacy</dt><dd>${e(initialAdequacy(p).status)}</dd></div><div class="fact"><dt>${p.reviewedAt?'Source review':'Compiled'}</dt><dd>${p.reviewedAt?dateLabel(p.reviewedAt):'October 19, 2026'}</dd></div></dl></section><div class="profile-layout"><nav class="contents" aria-label="On this page"><span class="filter-label">In this profile</span>${p.sections.map((s,i)=>`<a href="#section-${i+1}">${e(s.title)}</a>`).join('')}${p.researchGaps?.length?'<a href="#research-gaps">Research gaps</a>':''}${mapSection?'<a href="#historical-maps">Historical maps</a>':''}<a href="#sources">Sources &amp; further reading</a>${p.researchLeads?.length?'<a href="#reading-leads">Suggested reading leads</a>':''}${related.length?'<a href="#related">Related entries</a>':''}</nav><div class="profile-content">${p.relationshipNote?`<div class="relationship"><strong>Names &amp; relationships</strong>${e(p.relationshipNote)}</div>`:''}<div class="coverage-note"><strong>${p.coverageLevel==='developed-profile'?'An expanded introduction, with sources reviewed.':p.researchStatus==='researched'?'A cited introduction, with more to explore.':'A source guide for a deeper dive.'}</strong>${p.coverageLevel==='developed-profile'?'This profile develops several themes through identified sources. Citations connect each section to its evidence; remaining gaps appear below. It has not been reviewed or endorsed by the community.':p.researchStatus==='researched'?'This overview draws together the linked sources below. It is an introduction, and does not replace community-authored histories or a full scholarly study.':'This entry provides a brief orientation and an organized reading path. A comprehensive deep dive has not yet been completed. Follow the annotated sources and distinguish primary community accounts from outside reference material.'}</div>${p.initialAdequacy?`<section class="coverage-note" aria-label="Initial adequacy assessment"><strong>${e(initialAdequacy(p).status)}</strong><p>${e(initialAdequacy(p).rationale)}</p>${initialAdequacy(p).reviewedAt?`<p>Assessment recorded ${e(dateLabel(initialAdequacy(p).reviewedAt))}. This is separate from research completion and community review.</p>`:''}${initialAdequacy(p).remainingLimits.length?`<ul>${initialAdequacy(p).remainingLimits.map(limit=>`<li>${e(limit)}</li>`).join('')}</ul>`:''}</section>`:''}${p.originalId===16?`<details class="apache-image-credits" id="apache-image-credits"><summary>Backdrop photographs &amp; credits</summary><p>Publicly available object photographs connected to the broad Apache entry. Individual objects are not representative of every Apache nation.</p>${apacheCollage.images.map(image=>`<p><strong>${e(image.title)}</strong> — ${e(image.credit)} <a href="${e(image.source)}" target="_blank" rel="noopener noreferrer">Source &amp; image record</a> · <a href="${e(image.rightsUrl)}" target="_blank" rel="noopener noreferrer">${e(image.rights)}</a>. <span>${e(image.scope)}</span></p>`).join('')}<p>Image records and photographs reviewed October 24, 2026. Layout uses neutral earth-toned gradients; no generated cultural imagery.</p></details>`:''}${profileVisuals.credits(p,base,e)}${sections}${p.researchGaps?.length?`<section class="research-gaps" id="research-gaps"><h2>What needs further research</h2><ul>${p.researchGaps.map(g=>`<li>${e(g)}</li>`).join('')}</ul>${p.evidenceNotes?.length?`<p>${e(p.evidenceNotes.join(' '))}</p>`:''}</section>`:''}${mapSection}<section id="sources" data-profile-sources><div class="source-heading"><div class="eyebrow">Follow the reading path</div><h2>Sources &amp; further reading</h2><p>Open any title to read the original source. Annotations explain what each link can help you explore.</p></div><div class="source-filters" role="group" aria-label="Filter sources"><button class="active" data-source-filter="all" aria-pressed="true">All sources (${p.sources.length})</button><button data-source-filter="indigenous" aria-pressed="false">Indigenous-led (${p.sources.filter(s=>isIndigenousLed(s)).length})</button></div><p class="coverage-note" data-no-indigenous hidden>No Indigenous-led source is identified in this entry yet. This is a gap in this collection, and does not imply an absence of community knowledge or organization.</p>${p.sources.map((s,i)=>sourceCard(s,{index:i,profile:true})).join('')}</section>${researchLeadSection(p)}${related.length?`<section class="related" id="related"><div class="eyebrow">Names in context</div><h2>Continue with related entries</h2><div class="related-links">${related.map(r=>`<a href="../${r.slug}/">${e(r.name)}<span aria-hidden="true">↗</span></a>`).join('')}</div><p class="filter-help">Related entries may represent alternate names, constituent communities, wider groupings, or historical connections. Read the naming notes before treating entries as equivalent.</p></section>`:''}<p class="print-label">Robey’s Atlas of Indigenous North America · Compiled October 19, 2026 · ${e(p.name)}</p></div></div></main>`,base);}
const sourcePage=document('The reading room','An annotated collection of Indigenous-led, government, museum, and academic sources for learning about Indigenous North America.',`<main id="main" class="wrap"><section class="page-hero"><div class="eyebrow">The reading room</div><h1>Let the sources<br>open the story.</h1><p>Browse ${allSources.length} resources linked throughout the directory. Start with community-published accounts, then explore language projects, archives, histories, and wider context.</p><p><a href="../reading-leads/">Explore ${leadCatalog.documents.length} supplied reading collections awaiting review →</a></p></section><div class="search-box"><label class="search-icon" for="source-search" aria-label="Search sources">⌕</label><input id="source-search" type="search" placeholder="Search a nation, publisher, or topic…" aria-label="Search the source library"></div><div class="source-page-layout"><aside class="filters"><div class="filter-group"><label class="filter-label" for="source-type">Source perspective</label><select id="source-type"><option value="">All publishers</option>${options(types)}</select></div><div class="filter-group"><label class="filter-label" for="source-topic">Topic</label><select id="source-topic"><option value="">All topics</option>${options(['Identity','History','Homelands','Language','Culture','Government','Contemporary','Directories'])}</select></div><div class="filter-group filter-explanation"><p class="filter-help">Sources reflect their publishers’ perspectives and dates. A government directory describes an administrative system; a community account has a different purpose.</p><p class="filter-help">Outside archives can contain outdated terminology. The annotations and profile notes provide a starting point for reading critically.</p></div></aside><div class="source-list" data-source-list><div class="source-result-count" id="source-result-count" role="status" aria-live="polite">${allSources.length} sources</div>${allSources.map((s,i)=>sourceCard(s,{index:i,base:'../'})).join('')}<p class="empty" id="no-sources" hidden>No sources match these filters. Try another name or topic.</p><button class="load-more" id="source-more" hidden>Show more sources</button></div></div></main>`,'../','sources');
const about=document('Our approach','How Nations Atlas organizes names, relationships, research coverage, and sources.',`<main id="main" class="wrap"><section class="page-hero"><div class="eyebrow">Our approach</div><h1>A place to begin.<br>A way to go deeper.</h1><p>This atlas turns a starting list of 454 names into an accessible research directory. It preserves the original entries, adds supported omissions, and places sources alongside the reading.</p></section><article class="prose"><section id="coverage"><h2>What is here so far</h2><p class="count-block">${total} entries · ${addedCount} additions · ${minimumCollections} collections with 12+ inspected sources · ${expandedCount} expanded profiles · ${researched-expandedCount} brief cited overviews · ${profiles.filter(p=>p.researchStatus==='source-guide').length} source guides · ${allSources.length} unique resources</p><p>Every original entry has its own accessible page. The depth varies, and the site labels that difference. An <strong>expanded profile</strong> develops several themes with section citations, a recorded source-review date, and explicit gaps. A <strong>cited overview</strong> is a shorter introduction drawn from identified sources. A <strong>source guide</strong> is a shorter orientation with annotated reading. We aim for <strong>about twelve excellent, directly relevant inspected sources per collection</strong>, with more where useful. Five or six excellent sources can be sufficient when careful research cannot find further strong, relevant works and a recorded coverage review supports an adequate initial introduction. Neither count automatically establishes adequacy. Duplicate mirrors, bare homepages, passing mentions, and unread bibliographies do not increase the substantive inspected count. Existing profiles need a separate coverage assessment and honest remaining gaps. A recorded content check can cover identified sections or an available excerpt; annotations state such limits. Source quantity and these editorial labels do not mean that a comprehensive, community-reviewed deep dive is complete. <a href="../index.html?depth=developed-profile#directory">Browse the expanded profiles</a>.</p><p>The intended next stage is a fuller researched article for each entry: identity and names; homelands and historical change; language and cultural life; governance and contemporary community priorities; and a bibliography with community voices at its center. Gaps in this collection are research tasks, not evidence that a people has no contemporary presence.</p></section><section id="names"><h2>Names need context</h2><p>The starting list mixes peoples, political nations, individual communities, language groupings, and historical names. It also includes overlapping names. These are kept as separate access points so readers can find the name they know; naming notes and related entries explain relationships where the sources support them.</p><p>For example, a broad entry such as Pueblo is a route into multiple distinct communities. A term such as Ohlone also covers distinct communities and identities. Some entries use an outside name, while others use a community’s own name. A cross-link alone never establishes that two communities are interchangeable.</p><p>Search ignores accents and common apostrophe differences to make names easier to find, while displayed names retain their spelling. Preferred and alternate names are included where research established them. The atlas does not determine citizenship, identity, or recognition.</p></section><section><h2>Begin with Indigenous voices</h2><p>Profiles prioritize sources published by the people or nation concerned, community cultural organizations, language programs, and Indigenous representative bodies. Sources are labeled by origin or format and annotated for relevance. Reporting and public interviews are identified separately; annotations distinguish an author’s own account from an institution’s policy. Government, university, museum, and archival resources add context, but do not replace community perspectives.</p><p>The Smithsonian’s <a href="https://americanindian.si.edu/nk360/about/essential-understandings" target="_blank" rel="noopener noreferrer">Native Knowledge 360° framework</a>, developed with Native communities, offers useful guidance for understanding diverse and continuing Indigenous lives. It informs this directory’s emphasis on specific communities and contemporary context.</p></section><section id="research-standard"><h2>How the research develops</h2><p>Each entry moves through source discovery, reading and relevance checks, synthesis with section citations, and editorial review. We prioritize the relevant nation’s own publications, identify the scope and date of outside accounts, and distinguish a proposed project from a completed result. A working URL alone does not establish that a source supports a claim.</p><p>Expanded profiles record unresolved questions instead of filling gaps with assumptions. When dates conflict, the text attributes the disagreement or uses a supported date range. Language endangerment is not evidence that a people has disappeared. Umbrella names, individual governments, historical towns, and related languages require separate treatment.</p><p>The current priority is the historical map room, followed by deeper research for Idaho, Minnesota and Texas. Earlier alphabetical research and its open gaps remain preserved. ${aMinimumCollections} of ${aProfiles.length} A collections currently contain at least 12 inspected substantive resources. The remaining A entries require the same careful reading, fuller articles, and evidence review. A smaller collection can be adequate when its documented evidence and search limits support that assessment. Reaching twelve leaves stated gaps and community review open. <a href="../index.html?letter=A#directory">Browse all A entries</a>. Quality depends on relevant, traceable evidence and breadth of perspectives. The twelve-source filter records quantity; initial adequacy, research completion and community review are separate assessments. <a href="../index.html?depth=reviewed-minimum#directory">Browse collections with 12 or more inspected sources</a>, or <a href="../data/research-progress.json">view the progress record</a>.</p></section><section><h2>Scope and completeness</h2><p>The directory follows the starting list across what are now Canada, the United States, Mexico, and Central America, with additional entries where verified sources support them. Modern country lines do not define the limits of Indigenous homelands. Regional labels are broad finding aids, and are not territorial boundaries.</p><p>This is an expanding collection, not an exhaustive list. The number of entries must not be read as the number of distinct Indigenous nations. Administrative lists also have specific limits: the <a href="https://www.bia.gov/service/tribal-leaders-directory" target="_blank" rel="noopener noreferrer">U.S. Tribal Leaders Directory</a>, <a href="https://services.sac-isc.gc.ca/fnp/main/Index.aspx?lang=eng" target="_blank" rel="noopener noreferrer">Canada’s First Nation Profiles</a>, and <a href="https://atlas.inpi.gob.mx/" target="_blank" rel="noopener noreferrer">Mexico’s INPI atlas</a> organize information for different purposes.</p></section><section><h2>How to read a profile</h2><ol><li>Read the identity and naming notes, including relationships to other entries.</li><li>Use the cited sections for orientation. Section citations jump to the supporting source cards.</li><li>Start with Indigenous-led sources where available. The annotations explain what each resource contributes.</li><li>Follow related communities and compare sources’ dates, scope, and authorship.</li><li>Save entries to your browser’s reading list, or print a profile with its source URLs.</li></ol></section><section><h2>Contributed reading leads</h2><p>Links from ${leadCatalog.documents.length} supplied studies are organized in <a href="../reading-leads/">suggested reading collections</a> on the relevant profiles. These preserve promising references while original sources are checked. Bibliographic labels from supplied documents are provisional. Reviewed source cards and content-check dates remain separate; suggested links do not inflate substantive inspected-source counts. Historical topic collections can span distinct communities without treating them as interchangeable.</p></section><section><h2>Access to sources</h2><p>Excellent sources may be freely available or require a subscription, account, or library access. Limited access is acceptable in this collection. Annotations identify verified access requirements where relevant and describe the material actually inspected. A review of selected pages or an excerpt does not imply that the entire work was read. Valuable references awaiting inspection remain further-reading leads, separate from completed content checks.</p></section><section id="map-method"><h2>Explore by modern region</h2><p>The <a href="../index.html#map">interactive map</a> and <a href="../regions/">text region list</a> link familiar modern places to existing directory entries. The lists are an incomplete, growing research index. Historical associations and present community or government locations are labeled separately; a government seat is not a homeland boundary, and a listing does not imply presence throughout a region. An empty list means regional evidence has not yet been curated.</p><p>Outlines are generalized administrative shapes from <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">Natural Earth, public domain</a>, rendered with an Albers equal-area projection. They are navigation aids, not Indigenous territorial boundaries or legal determinations. <a href="../data/map-provenance.json">Boundary provenance</a> · <a href="../data/region-associations.json">Regional evidence index</a> · <a href="../data/map-coverage.json">Coverage record</a>.</p></section><section id="historic-landscape-map"><h2>c.16th-century Indigenous nations map</h2><p>The homepage includes Peter Klumpenhower (Diné), <em>Indigenous American Nations, c.16th Century</em>, second edition (2024), as a contemporary reconstruction of approximate locations around the 1500s. It is not a primary map from that time, and the creator notes that overlapping territories were simplified for readability and that the map can be improved. The creator dedicates the map and its geometry to the public domain; the Atlas provides a courtesy credit and links to the creator's correction notes and reuse statement. The map is useful for broad orientation, not as a definitive or comprehensive territorial boundary source. <a href="../data/indigenous-landscape-map.json">Download the image provenance and limits</a>.</p></section><section id="historical-maps"><h2>The historical map room</h2><p>The <a href="../historical-maps/">historical map collection</a> links authentic archival maps with dates, creators, source records and inspection notes. Some records have reusable previews; others remain links to the holding archive. Historical classifications and colonial or government boundaries are not current Indigenous territories. Copies are identified, and image credits and reuse terms are recorded with each item. No generated maps or images are used.</p></section><section id="map-backgrounds"><h2>Historical map backgrounds</h2><p>Two authentic images supplied from the <a href="https://guides.loc.gov/native-american-spaces/featured-maps">Library of Congress featured-map guide</a> decorate the homepage as backgrounds. The original pixels are retained; layout cropping and translucent overlays keep text readable. No generated imagery is used.</p><ul><li><a href="https://www.loc.gov/item/2005625337/">Catawba deerskin map: archival reproduction</a>. Indigenous maker and colonial copyist unnamed; the map is associated with Francis Nicholson. The guide identifies a 1929 reproduction of an early eighteenth-century copied map, based on an Indigenous draught. Neither a particular nation nor an individual maker is established. The supplied image bears a British Museum Add.MS4723 mark; its exact scan provenance and identity as the LOC 1929 photostat are unconfirmed. LOC and Newberry provide historical interpretation; neither is asserted as this file’s digitizer.</li><li><a href="https://www.loc.gov/item/97683586/">Manatvs gelegen op de Noot Riuier</a>. Joan Vinckeboons (Vingboons); the guide describes a copy around1665 after a 1639 map. Catalogue dating differs. This is Dutch colonial cartography, with Indigenous settlements represented. Credit: Library of Congress, Geography and Map Division.</li></ul><p>The inspected LOC records permit reuse subject to item-specific advisories; no contrary advisory was observed. Actual supplied images and the guide were inspected; direct item requests were blocked during this update, so record-rights review used saved indexed catalogue text. <a href="../data/homepage-map-backgrounds.json">Image provenance and display notes</a>.</p></section><section id="directory-design"><h2>Directory card artwork</h2><p>Each directory entry has its own decorative colors and composition. Abstract backdrops are interface artwork, not traditional cultural designs or historical evidence. Identified photographs retain their specific artist, subject, source and reuse terms below. <a href="../data/directory-card-designs.json">Card design and image register</a>.</p></section><section id="generated-background"><h2>Generated decorative background</h2><p>The warm illustrated page background was generated with OpenAI’s image tool at the Atlas owner’s request. It combines separate fictional scenes of carved-pole forms, stepped pyramids, bison hunting and salmon fishing. It is contemporary decoration, not an archival image, an authentic traditional artwork, a historical reconstruction, or evidence for a particular nation. Research photographs and historical maps retain their separate source records and credits.</p><p><a href="../assets/atlas-generated-collage-20261025.png">View the complete generated illustration</a> · <a href="../data/generated-background.json">Generation record and prompt</a></p><img class="generated-art-preview" src="../assets/atlas-generated-collage-20261025.png" width="1536" height="1024" alt="Generated illustrated collage with carved poles, stepped pyramids, bison hunting and river fishing scenes on golden parchment." loading="lazy"></section><h2 id="brand-image">Atlas brand image</h2><p>The collage used as the Atlas brand image was supplied and selected by the Atlas owner. Individual component credits were not included with the file. It is presented as brand artwork and does not serve as evidence for any nation profile.</p><p><a href="../assets/robeys-atlas-brand-collage.jpg">View the complete brand image</a> · <a href="../data/brand-image.json">Image record</a></p><p><strong>Small header emblem.</strong> The separate image beside the Atlas name was supplied and selected by the owner for this small header placement. Its creator and a third-party reuse license were not supplied. It is brand artwork, not historical or geographic evidence. <a href="../data/header-brand-image.json">Header image record</a>.</p><section id="photography"><h2>Photography &amp; credits</h2><p><strong>Map sidebar artwork:</strong> Acoma Pueblo artist, name unrecorded, <em>Water Jar</em>, about 1880. The Metropolitan Museum of Art, Museum Accession, X.2.418. <a href="https://www.metmuseum.org/art/collection/search/318293">Artwork and image source</a> · <a href="https://www.metmuseum.org/hubs/open-access">Public Domain / Met Open Access (CC0)</a>. The existing photograph is unchanged; CSS applies background cropping and a translucent readability overlay. <a href="../data/homepage-map-sidebar-art.json">Display record</a>.</p><p><strong>Language-map invitation:</strong> El Osario at Chichén Itzá, photographed by Álvaro de la Paz Franco on January 19, 2025. <a href="https://commons.wikimedia.org/wiki/File:Chich%C3%A9n_Itz%C3%A1_-_Osario_02.jpg" target="_blank" rel="noopener noreferrer">Original photograph and credit</a> · <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noopener noreferrer">CC0 1.0</a>. The complete frame is resized and compressed for the web; the panel applies layout cropping and a dark overlay. This architectural photograph decorates the invitation and does not establish the Smithsonian map’s coverage. <a href="../data/language-map-feature-photo.json">Photo inspection and display record</a>.</p><p>The photographs identify particular places. They are visual context for this atlas; each nation’s own history and cultural sources remain central to its profile.</p><ul><li><a href="https://commons.wikimedia.org/wiki/File:Canyon_de_Chelly_at_sunset.jpg" target="_blank" rel="noopener noreferrer">Canyon de Chelly at sunset</a>, Margie Roesch, July 2, 2011. Licensed <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a>. The web version is resized and recompressed, with cropping and a color overlay applied by the page layout. The adapted image remains available under that license. Canyon de Chelly is on Navajo Nation land; see the <a href="https://www.jpl.nasa.gov/news/nasas-perseverance-mars-rover-mission-honors-navajo-language/" target="_blank" rel="noopener noreferrer">NASA/JPL account</a>.</li><li><a href="https://commons.wikimedia.org/wiki/File:Overlooking_Lamar_Valley_and_River_(51285688873).jpg" target="_blank" rel="noopener noreferrer">Overlooking Lamar Valley and River</a>, NPS/Jacob W. Frank, June 27, 2021. National Park Service photograph, public domain in the United States. This former site-background photograph is retained with its resized web copy and original source credit; the shared decorative background is now generated artwork. The source record retains the original attribution and rights information.</li></ul><p><a href="../assets/canyon-de-chelly.webp">Download the Canyon de Chelly web image</a> · <a href="../assets/lamar-valley.webp">Download the Lamar Valley web image</a></p>${homeImageCredits()}</section><section><h2>Editorial limits and maintenance</h2><p>The collection began on October 19, 2026; the latest research update is ${dateLabel(latestResearchDate)}. It is an independent research collection and has not been reviewed or endorsed by the listed communities. Links can change, and legal status, officeholders, population estimates, and community initiatives require checking against current community sources.</p><p>Only publicly available sources are linked. A public reference is not permission to reproduce or interpret restricted cultural knowledge. Short summaries and annotations lead readers to the publishers’ original work.</p><p>The <a href="../data/profiles.json" download>downloadable research data</a> keeps the profile text, source metadata, original-list identifiers, research labels, and relationship notes together. It can support continued research and corrections without losing the evidence behind an entry.</p></section></article></main>`,'../','about');
function write(name,content){const p=path.join(dist,name);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,content,'utf8');}
write('index.html',document('Indigenous nations & peoples','Explore Indigenous nations and peoples of North America through cited profiles, naming notes, and annotated sources.',home));
