const progress=profiles.map(p=>({originalId:p.originalId||null,name:p.name,slug:p.slug,priorityGroup:p.mapRegions?.some(r=>['US-ID','US-MN','US-TX'].includes(r.id))?'Idaho, Minnesota and Texas priority':'Later alphabetical research',depth:status(p),listedSources:p.sources.length,suggestedReadingLinks:p.researchLeads?.length||0,recordedContentChecks:checkedSources(p),supportingContentChecks:p.sources.filter(s=>s.contentReviewedAt&&s.countsTowardMinimum===false).length,minimumSources,sourceMinimumReached:checkedSources(p)>=minimumSources,sourceTarget:minimumSources,initialAdequacy:initialAdequacy(p),reviewedAt:p.reviewedAt||null,remainingGaps:p.researchGaps||[],communityReview:p.communityReview||'Not recorded',researchComplete:p.researchComplete===true}));
